mapper.sql:
exists (
    select 1
    from competition_apply_info auth
    where auth.del_flag = '0'
      and auth.competition_series_id = m.competition_series_id
      and auth.team_code collate utf8mb4_general_ci = m.team_code collate utf8mb4_general_ci
      and (
          auth.leader_teacher_id = #{teacherUserId}
          or (
              auth.user_id = #{teacherUserId}
              and auth.competition_role_name = '指导教师'
          )
      )
)

